static inline vu_block vu_bail(MotorstormVehicleState* s, uint32_t address) {
    s->bail_pc = address;
    return VU_BAIL;
}
/* Entry by address: a call target, an indirect call target or a return address. The extent
   ends at its own return address. A return address inside the kernel continues the caller. */
static vu_block vu_enter(MotorstormVehicleState* s, uint32_t address) {
    const uint32_t a = address & 0x3ffffu;
    if (a == MOTORSTORM_VEHICLE_RETURN) return VU_DONE;
    if ((a & 3u) || !vu_index[a >> 2]) return vu_bail(s, a);
    return (vu_block)vu_index[a >> 2];
}
static inline vu_block vu_ret(MotorstormVehicleState* s, unsigned n) {
    return vu_enter(s, s->gpr[n]._u32[0]);
}

