static int vu_run(MotorstormVehicleState* s, uint32_t address) {
    s->bail_pc = 0;
    s->blocks = 0;
    vu_block b = vu_enter(s, address);
    while (b > VU_DONE && b != VU_BAIL) {
        ++s->blocks;
        s->pc = vu_address[b - 1];
        b = vu_blocks[b - 1](s);
    }
    return b == VU_DONE;
}

int motorstorm_vehicle_update(MotorstormVehicleState* s) {
    return vu_run(s, MOTORSTORM_VEHICLE_ENTRY);
}

/* Starts at a ported segment: the lifted path has run the first block of the extent. */
int motorstorm_vehicle_update_at(MotorstormVehicleState* s, uint32_t address) {
    return vu_run(s, address & 0x3ffffu);
}
